# 2) текущая версия кэша
old = '> **Текущая версия кэша:** `kipia-v483`'
new = '> **Текущая версия кэша:** `kipia-v484`'
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)

# 3) формат бампа
old = 'kipia-v483` → `kipia-v484` (для kip8)'
new = 'kipia-v484` → `kipia-v485` (для kip8)'
