s = s.replace(old, new)

# 4) счётчик тестов
old = '# Ожидается: 4669 passed, 0 failed (kip8; в kip8test — 4663 passed, 0 failed)'
new = '# Ожидается: 4697 passed, 0 failed (kip8; в kip8test — 4691 passed, 0 failed)'
